from pathlib import Path

p = Path(__file__).resolve().parents[1] / 'index.html'
s = p.read_text(encoding='utf-8')

# v4.6: service attributes, detailed Place maintenance, and Google attribute sync.
if 'Place詳細メンテナンス' in s and 'v4.6' in s:
    print('v4.6 already patched')
    raise SystemExit(0)
if 'v4.5' not in s:
    raise SystemExit('Expected v4.5 index.html')
s = s.replace('v4.5', 'v4.6')

# Styling for the detailed Place editor.
css_needle = '.badge{display:inline-block;border-radius:999px;padding:2px 6px;background:#edf1f3;color:#52606b;font-size:10px}'
css_add = '''.detail-editor{margin-top:14px;border:1px solid #dfe5e8;border-radius:14px;padding:14px;background:#fbfcfc}.detail-editor textarea{width:100%;min-height:76px;border:1px solid #ccd3da;border-radius:10px;padding:9px;font:inherit;resize:vertical}.detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.detail-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.detail-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.detail-source{font-size:11px;color:#667085}.attr-note{font-size:11px;color:#667085;margin-top:5px}.point-table{min-width:1040px}'''
if css_needle not in s:
    raise SystemExit('CSS badge marker not found')
s = s.replace(css_needle, css_needle + css_add)
s = s.replace('@media(max-width:740px){.api-grid{grid-template-columns:1fr}', '@media(max-width:740px){.detail-grid{grid-template-columns:1fr}.api-grid{grid-template-columns:1fr}')

# Add a Google attribute bulk button to the API tools.
api_marker = '''<div id="googleVerifyProgress" class="small" style="margin-top:8px"></div><div id="bulkVerifyStatus" class="small" style="margin-top:5px"></div>'''
api_repl = '''<div id="googleVerifyProgress" class="small" style="margin-top:8px"></div><div id="bulkVerifyStatus" class="small" style="margin-top:5px"></div><div style="margin-top:9px"><button class="alt" onclick="bulkFetchGoogleAttributes()">Google属性を一括取得</button><button id="attrStopBtn" class="alt" onclick="stopBulkAttributes()" disabled>属性取得を停止</button><div id="bulkAttrStatus" class="small"></div><div class="attr-note">Google Place IDがあるPlaceから、通常営業時間・今週営業時間・家族向き・トイレ有無などを取得します。</div></div>'''
if api_marker not in s:
    raise SystemExit('Google progress marker not found')
s = s.replace(api_marker, api_repl)

# Extend the registered point manager with a detail editor.
old_manager_tail = '''<div id="pointCount" class="small"></div><div class="point-table-wrap"><table class="point-table"><thead><tr><th>種別</th><th>名称</th><th>カテゴリ</th><th>緯度</th><th>経度</th><th>状態</th><th>操作</th></tr></thead><tbody id="pointBody"></tbody></table></div></div>'''
new_manager_tail = '''<div id="pointCount" class="small"></div><div class="point-table-wrap"><table class="point-table"><thead><tr><th>種別</th><th>名称</th><th>カテゴリ</th><th>緯度</th><th>経度</th><th>状態</th><th>操作</th></tr></thead><tbody id="pointBody"></tbody></table></div><div id="placeDetailEditor" class="detail-editor" style="display:none"><div class="detail-head"><div><div class="result-title">Place詳細メンテナンス</div><div id="detailPlaceName" style="font-weight:800"></div><div id="detailPlaceSource" class="detail-source"></div></div><button class="alt" onclick="closePlaceDetail()">閉じる</button></div><div class="detail-grid" style="margin-top:10px"><div><label>営業日</label><input id="dDays"></div><div><label>営業時間（共通/簡易）</label><input id="dHours"></div><div><label>定休日</label><input id="dClosed"></div><div><label>24時間</label><select id="d24"><option value="">要確認</option><option value="○">○</option><option value="×">×</option></select></div><div><label>家族向き</label><select id="dFamily"><option value="">要確認</option><option value="○">○ 家族向き</option><option value="△">△ 条件次第</option><option value="×">× 大人向き</option></select></div><div><label>雨天向き</label><select id="dRain"><option value="">要確認</option><option value="○">○ 雨でも利用しやすい</option><option value="△">△ 一部可能</option><option value="×">× 屋外中心</option></select></div><div><label>屋内外</label><select id="dIndoor"><option value="">要確認</option><option value="屋内">屋内</option><option value="屋外">屋外</option><option value="両方">両方</option></select></div><div><label>トイレあり</label><select id="dToilet"><option value="">要確認</option><option value="○">○</option><option value="×">×</option></select></div><div><label>トイレ一般利用</label><select id="dToiletPublic"><option value="">要確認</option><option value="○">○ 一般利用可</option><option value="施設利用者向け">施設利用者向け</option><option value="要確認">要確認</option><option value="×">×</option></select></div><div><label>多目的トイレ</label><input id="dAccessibleToilet" placeholder="例：オストメイト・ベビーベッド"></div><div><label>自転車貸出</label><select id="dBike"><option value="">なし/要確認</option><option value="○">○ 貸出あり</option><option value="×">×</option></select></div><div><label>Google主要タイプ</label><input id="dGoogleType" readonly></div></div><div style="margin-top:10px"><label>曜日別営業時間</label><textarea id="dWeeklyHours" placeholder="Googleから取得または手動入力"></textarea></div><div style="margin-top:8px"><label>今週営業時間（祝日・臨時変更を含むGoogle情報）</label><textarea id="dCurrentHours" readonly></textarea></div><div class="detail-actions"><button onclick="savePlaceDetail()">詳細を保存</button><button class="alt" onclick="fetchGoogleAttributesForSelected()">Google属性を取得</button><button class="alt" onclick="showDetailedPlaceOnMap()">地図で見る</button></div><div id="detailStatus" class="small"></div></div></div>'''
if old_manager_tail not in s:
    raise SystemExit('point manager tail not found')
s = s.replace(old_manager_tail, new_manager_tail)

# Add attribute storage key.
s = s.replace("function editKey(src,id){return`point-edit:${src}:${id}`}", "function editKey(src,id){return`point-edit:${src}:${id}`}function attrKey(id){return`place-attr:${id}`}")

# Apply stored attribute edits after the regular point edits.
apply_marker = '''function rebuild(){'''
apply_attrs = r'''function applyAttrEdits(){P.forEach(p=>{try{let x=JSON.parse(localStorage.getItem(attrKey(p.place_id)));if(x)Object.assign(p,x)}catch(e){}})}
'''
if apply_marker not in s:
    raise SystemExit('rebuild marker not found')
s = s.replace(apply_marker, apply_attrs + apply_marker, 1)

# Google-normalized opening hours take precedence in planner filtering.
open_old = '''function isOpenDay(p){const wd=$('weekday').value,closed=p['定休日']||'',days=p['営業日']||'';if(closed.includes(wd))return false;if(days&&days!=='毎日'&&!days.includes(wd)&&!days.includes('平日'))return false;if(days.includes('平日')&&['土','日'].includes(wd))return false;return true}function openAt(p,min){if(!isOpenDay(p))return false;let h=(p['営業時間']||'').replaceAll('頃','');if(!h||h.includes('24時間'))return true;let rs=[...h.matchAll(/(\\d{1,2}):(\\d{2})\\s*[-〜~]\\s*(\\d{1,2}):(\\d{2})/g)];if(!rs.length)return true;return rs.some(x=>{let a=+x[1]*60+ +x[2],b=+x[3]*60+ +x[4];if(b===0)b=1440;return min>=a&&min<=b})}'''
open_new = r'''function isOpenDay(p){const wd=$('weekday').value,closed=p['定休日']||'',days=p['営業日']||'';if(closed.includes(wd))return false;if(days&&days!=='毎日'&&!days.includes(wd)&&!days.includes('平日'))return false;if(days.includes('平日')&&['土','日'].includes(wd))return false;return true}function googleRegularOpenAt(p,wd,min){if(p['24時間']==='○')return true;let raw=p['Google営業時間JSON'];if(!raw)return null;try{let m=JSON.parse(raw),arr=m[wd];if(!arr||!arr.length)return false;return arr.some(v=>{if(v==='24時間')return true;let x=String(v).match(/(\d{1,2}):(\d{2})-(\d{1,2}):(\d{2})/);if(!x)return true;let a=+x[1]*60+ +x[2],b=+x[3]*60+ +x[4];if(b===0)b=1440;return b<a?(min>=a||min<=b):(min>=a&&min<=b)})}catch(e){return null}}function openAt(p,min){let g=googleRegularOpenAt(p,$('weekday').value,min);if(g!==null)return g;if(!isOpenDay(p))return false;let h=(p['営業時間']||'').replaceAll('頃','');if(!h||h.includes('24時間'))return true;let rs=[...h.matchAll(/(\d{1,2}):(\d{2})\s*[-〜~]\s*(\d{1,2}):(\d{2})/g)];if(!rs.length)return true;return rs.some(x=>{let a=+x[1]*60+ +x[2],b=+x[3]*60+ +x[4];if(b===0)b=1440;return min>=a&&min<=b})}'''
if open_old not in s:
    raise SystemExit('openAt block not found')
s = s.replace(open_old, open_new)

# Add a Detail button to the point list.
button_old = '''<button onclick="savePoint(this)">保存</button><button class="alt" onclick="showPoint(this)">地図</button>'''
button_new = '''<button onclick="savePoint(this)">保存</button><button class="alt" onclick="showPoint(this)">地図</button><button class="alt" onclick="editPointDetail(this)">詳細</button>'''
if button_old not in s:
    raise SystemExit('point buttons not found')
s = s.replace(button_old, button_new)

# Detailed editor helpers and Google Places attribute sync.
helper_marker = '''function exportPointOverrides(){'''
helpers = r'''let detailPlaceIndex=null,attrBulkRunning=false,attrBulkStop=false;function selectSet(id,v){let el=$(id);el.value=[...el.options].some(o=>o.value===String(v??''))?String(v??''):''}function guessFamily(p){if(p['家族向き'])return p['家族向き'];return /(居酒屋|バー|スナック|焼き鳥)/.test(p['カテゴリ']||'')?'△':''}function guessIndoor(p){if(p['屋内外'])return p['屋内外'];let c=(p['カテゴリ']||'')+' '+(p['種別']||'');if(/(公園|自然|湿原|景勝|史跡|神社|寺院|湖畔|街道|古墳)/.test(c))return '屋外';if(/(飲食|レストラン|カフェ|博物館|美術館|図書館|コンビニ|公衆トイレ|温泉|観光案内)/.test(c))return '屋内';return ''}function guessRain(p){if(p['雨天向き'])return p['雨天向き'];let i=guessIndoor(p);return i==='屋内'?'○':i==='両方'?'△':i==='屋外'?'×':''}function editPointDetail(btn){let tr=btn.closest('tr');if(tr.dataset.source!=='place'){alert('詳細属性はPlaceで管理します。バス停はGTFSデータとして管理しています。');return}openPlaceDetail(+tr.dataset.i)}function openPlaceDetail(i){let p=P[i];if(!p)return;detailPlaceIndex=i;$('placeDetailEditor').style.display='block';$('detailPlaceName').textContent=p['名称'];$('detailPlaceSource').textContent=(p['情報源']||'')+(p['Google属性確認日']?' / Google属性確認 '+p['Google属性確認日']:'');$('dDays').value=p['営業日']||'';$('dHours').value=p['営業時間']||'';$('dClosed').value=p['定休日']||'';selectSet('d24',p['24時間']||'');selectSet('dFamily',guessFamily(p));selectSet('dRain',guessRain(p));selectSet('dIndoor',guessIndoor(p));selectSet('dToilet',p['トイレあり']||'');selectSet('dToiletPublic',p['トイレ一般利用']||'');$('dAccessibleToilet').value=p['多目的トイレ']||'';selectSet('dBike',p['自転車貸出']||'');$('dWeeklyHours').value=p['営業時間_曜日別']||'';$('dCurrentHours').value=p['今週営業時間_Google']||'';$('dGoogleType').value=p['Google主要タイプ']||'';$('detailStatus').textContent='';$('placeDetailEditor').scrollIntoView({behavior:'smooth',block:'nearest'})}function closePlaceDetail(){$('placeDetailEditor').style.display='none';detailPlaceIndex=null}function detailValues(){return{'営業日':$('dDays').value.trim(),'営業時間':$('dHours').value.trim(),'定休日':$('dClosed').value.trim(),'24時間':$('d24').value,'家族向き':$('dFamily').value,'雨天向き':$('dRain').value,'屋内外':$('dIndoor').value,'トイレあり':$('dToilet').value,'トイレ一般利用':$('dToiletPublic').value,'多目的トイレ':$('dAccessibleToilet').value.trim(),'自転車貸出':$('dBike').value,'営業時間_曜日別':$('dWeeklyHours').value.trim()}}function savePlaceDetail(){if(detailPlaceIndex===null)return;let p=P[detailPlaceIndex],v=detailValues();Object.assign(p,v);localStorage.setItem(attrKey(p.place_id),JSON.stringify(v));$('detailStatus').innerHTML='<span class="okmsg">詳細属性を保存しました。</span>';rebuild()}function showDetailedPlaceOnMap(){let p=P[detailPlaceIndex];if(p?.latitude&&p?.longitude)map.setView([+p.latitude,+p.longitude],18)}function pad2(n){return String(n).padStart(2,'0')}const JPDAYS=['日','月','火','水','木','金','土'];function openingHoursMap(oh){let m=Object.fromEntries(JPDAYS.map(d=>[d,[]]));if(!oh?.periods?.length)return m;for(let pr of oh.periods){let o=pr.open,c=pr.close;if(!o)continue;if(!c){if(o.day===0&&o.hour===0&&o.minute===0)JPDAYS.forEach(d=>m[d]=['24時間']);else m[JPDAYS[o.day]]=['24時間'];continue}let a=`${pad2(o.hour)}:${pad2(o.minute)}`,b=(c.day!==o.day&&c.hour===0&&c.minute===0)?'24:00':`${pad2(c.hour)}:${pad2(c.minute)}`;m[JPDAYS[o.day]].push(`${a}-${b}`)}return m}function deriveHoursIntoPlace(p,oh){if(!oh)return;let m=openingHoursMap(oh),open=JPDAYS.filter(d=>m[d].length),closed=JPDAYS.filter(d=>!m[d].length);p['Google営業時間JSON']=JSON.stringify(m);p['営業日']=open.length===7?'毎日':open.join('・');p['定休日']=closed.join('・');let vals=[...new Set(open.map(d=>m[d].join(' / ')))];p['営業時間']=vals.length===1?vals[0]:'曜日別';p['24時間']=open.length===7&&open.every(d=>m[d].includes('24時間'))?'○':'×';p['営業時間_曜日別']=(oh.weekdayDescriptions||[]).join('\n')}function inferRainFromGoogle(p,gp){if(p['雨天向き'])return;let t=(gp.primaryType||'')+' '+(p['カテゴリ']||'');if(/restaurant|cafe|museum|library|convenience_store|store|shopping|spa|lodging|レストラン|カフェ|博物館|美術館|図書館|コンビニ|温泉/.test(t))p['雨天向き']='○';else if(/park|natural|hiking|公園|自然|湿原|景勝/.test(t))p['雨天向き']='×';else p['雨天向き']='△'}async function fetchGoogleAttributesForPlace(i,silent=false){let p=P[i];if(!p?.google_place_id){if(!silent)$('detailStatus').innerHTML='<span class="errmsg">Google Place IDがありません。先にGoogle候補検索で場所を確定してください。</span>';return false}await ensureGooglePlaces();const {Place}=await google.maps.importLibrary('places');let gp=new Place({id:p.google_place_id,requestedLanguage:'ja',requestedRegion:'jp'});let res=await gp.fetchFields({fields:['regularOpeningHours','currentOpeningHours','isGoodForChildren','isGoodForGroups','hasRestroom','primaryType','businessStatus']});gp=res.place||gp;deriveHoursIntoPlace(p,gp.regularOpeningHours);p['今週営業時間_Google']=(gp.currentOpeningHours?.weekdayDescriptions||[]).join('\n');if(gp.isGoodForChildren===true)p['家族向き']='○';else if(gp.isGoodForChildren===false)p['家族向き']='△';if(gp.hasRestroom===true)p['トイレあり']='○';else if(gp.hasRestroom===false)p['トイレあり']='×';p['Google主要タイプ']=gp.primaryType||'';p['Google家族向き']=gp.isGoodForChildren===true?'true':gp.isGoodForChildren===false?'false':'';p['Googleグループ向き']=gp.isGoodForGroups===true?'true':gp.isGoodForGroups===false?'false':'';p['Googleトイレ']=gp.hasRestroom===true?'true':gp.hasRestroom===false?'false':'';p['Google営業状態']=gp.businessStatus||'';p['Google属性確認日']=new Date().toISOString().slice(0,10);inferRainFromGoogle(p,gp);let v={};for(let k of ['営業日','営業時間','定休日','24時間','家族向き','雨天向き','屋内外','トイレあり','トイレ一般利用','多目的トイレ','自転車貸出','営業時間_曜日別','今週営業時間_Google','Google営業時間JSON','Google主要タイプ','Google家族向き','Googleグループ向き','Googleトイレ','Google営業状態','Google属性確認日'])v[k]=p[k]||'';localStorage.setItem(attrKey(p.place_id),JSON.stringify(v));if(!silent){openPlaceDetail(i);$('detailStatus').innerHTML='<span class="okmsg">Google属性を取得しました。</span>'}return true}async function fetchGoogleAttributesForSelected(){if(detailPlaceIndex===null)return;try{await fetchGoogleAttributesForPlace(detailPlaceIndex,false);rebuild()}catch(e){$('detailStatus').innerHTML='<span class="errmsg">'+esc(e.message||String(e))+'</span>'}}function stopBulkAttributes(){attrBulkStop=true;$('bulkAttrStatus').textContent='停止要求を受け付けました。'}async function bulkFetchGoogleAttributes(){if(attrBulkRunning)return;let targets=P.map((p,i)=>({p,i})).filter(x=>x.p.google_place_id);if(!targets.length){$('bulkAttrStatus').textContent='Google Place IDがあるPlaceがありません。';return}attrBulkRunning=true;attrBulkStop=false;$('attrStopBtn').disabled=false;let ok=0,ng=0;for(let n=0;n<targets.length;n++){if(attrBulkStop)break;let x=targets[n];$('bulkAttrStatus').textContent=`${n+1}/${targets.length} ${x.p['名称']} の属性を取得中… 成功 ${ok} / 失敗 ${ng}`;try{if(await fetchGoogleAttributesForPlace(x.i,true))ok++;else ng++}catch(e){console.error(e);ng++}await new Promise(r=>setTimeout(r,180))}attrBulkRunning=false;$('attrStopBtn').disabled=true;rebuild();$('bulkAttrStatus').innerHTML=`<span class="okmsg">Google属性取得終了：</span> 成功 ${ok} / 失敗 ${ng}${attrBulkStop?'（途中停止）':''}`} 
'''
if helper_marker not in s:
    raise SystemExit('exportPointOverrides marker not found')
s = s.replace(helper_marker, helpers + helper_marker, 1)

# Export all dynamically added columns, not only the first CSV schema.
s = s.replace("let k=Object.keys(P[0]),t='\\ufeff'", "let k=[...new Set(P.flatMap(x=>Object.keys(x)))],t='\\ufeff'")

# Load the new service/utility Places file and apply attribute edits.
loader_old = "Promise.all([fetch('data/places.csv').then(r=>{if(!r.ok)throw Error('places.csv '+r.status);return r.text()}),fetch('data/places_extra.csv').then(r=>r.ok?r.text():''),loadTransitStops()]).then(([t,te,b])=>{P=parseCSV(t).concat(te?parseCSV(te):[]);B=b;applyCache();applyEdits();rebuild();"
loader_new = "Promise.all([fetch('data/places.csv').then(r=>{if(!r.ok)throw Error('places.csv '+r.status);return r.text()}),fetch('data/places_extra.csv').then(r=>r.ok?r.text():''),fetch('data/places_services.csv').then(r=>r.ok?r.text():''),loadTransitStops()]).then(([t,te,ts,b])=>{P=parseCSV(t).concat(te?parseCSV(te):[],ts?parseCSV(ts):[]);B=b;applyCache();applyEdits();applyAttrEdits();rebuild();"
if loader_old not in s:
    raise SystemExit('loader block not found')
s = s.replace(loader_old, loader_new)

p.write_text(s, encoding='utf-8')
print('patched index.html to v4.6 service attributes and detailed maintenance')
